package com.codeguardian.config;
import com.codeguardian.entity.*; import com.codeguardian.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.boot.CommandLineRunner; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Component; import java.time.LocalDateTime; import java.util.List;
@Component @RequiredArgsConstructor public class DataInitializer implements CommandLineRunner { private final UserRepository users; private final RoleRepository roles; private final PermissionRepository permissions; private final UserRoleRepository userRoles; private final RolePermissionRepository rolePermissions; private final BCryptPasswordEncoder encoder; public void run(String... args){initRoles();initPermissions();initLinks();initAdmin();} private void initRoles(){for(Role r:List.of(Role.builder().code("ADMIN").name("Administrator").description("Full system access").createdAt(LocalDateTime.now()).build(),Role.builder().code("REVIEWER").name("Reviewer").description("Can create reviews").createdAt(LocalDateTime.now()).build(),Role.builder().code("VIEWER").name("Viewer").description("Read-only review access").createdAt(LocalDateTime.now()).build()))if(roles.findByCode(r.getCode()).isEmpty())roles.save(r);} private void initPermissions(){for(Permission p:List.of(Permission.builder().code("QUERY").name("Query").description("Read tasks and reports").createdAt(LocalDateTime.now()).build(),Permission.builder().code("REVIEW").name("Review").description("Create code review tasks").createdAt(LocalDateTime.now()).build(),Permission.builder().code("CONFIG").name("Configuration").description("Modify configuration").createdAt(LocalDateTime.now()).build(),Permission.builder().code("ADMIN").name("Administration").description("Manage users and roles").createdAt(LocalDateTime.now()).build()))if(permissions.findByCode(p.getCode()).isEmpty())permissions.save(p);} private void initLinks(){link("ADMIN",List.of("QUERY","REVIEW","CONFIG","ADMIN"));link("REVIEWER",List.of("QUERY","REVIEW"));link("VIEWER",List.of("QUERY"));} private void link(String role,List<String> codes){Role r=roles.findByCode(role).orElseThrow();for(String code:codes){Permission p=permissions.findByCode(code).orElseThrow();if(!rolePermissions.existsByRoleIdAndPermissionId(r.getId(),p.getId()))rolePermissions.save(RolePermission.builder().roleId(r.getId()).permissionId(p.getId()).createdAt(LocalDateTime.now()).build());}} private void initAdmin(){User admin=users.findByUsername("admin").orElseGet(()->users.save(User.builder().username("admin").email("admin@codeguardian.ai").passwordHash(encoder.encode("admin123")).realName("System Administrator").status("ACTIVE").createdAt(LocalDateTime.now()).build()));Role role=roles.findByCode("ADMIN").orElseThrow();if(!userRoles.existsByUserIdAndRoleId(admin.getId(),role.getId()))userRoles.save(UserRole.builder().userId(admin.getId()).roleId(role.getId()).createdAt(LocalDateTime.now()).build());} }
